<script>
export default {
  name: "ImportPractitioners",

  data() {
    return {
      phase: "idle", // idle | selected | uploading | processing | done | error
      dragging: false,
      selectedFile: null,
      uploadPct: 0,
      jobId: null,
      procCurrent: 0,
      procTotal: 0,
      liveSaved: 0,
      liveExisting: 0,
      liveInvalid: 0,
      feedItems: [],
      feedCounter: 0,
      finalStats: {},
      hasInvalidFile: false,
      errorMsg: "",
      eventSource: null,
      procStartTime: null,
      sseErrorCount: 0,
    };
  },

  computed: {
    procPct() {
      if (!this.procTotal) return 0;
      return Math.round((this.procCurrent / this.procTotal) * 100);
    },
    successRate() {
      if (!this.finalStats.total) return 0;
      return Math.round((this.finalStats.saved / this.finalStats.total) * 100);
    },
    rowsPerSec() {
      if (!this.procStartTime || this.procCurrent === 0) return 0;
      const elapsed = (Date.now() - this.procStartTime) / 1000;
      return elapsed > 0 ? Math.round(this.procCurrent / elapsed) : 0;
    },
    etaText() {
      if (!this.rowsPerSec || !this.procTotal || !this.procCurrent) return "";
      const remaining = this.procTotal - this.procCurrent;
      if (remaining <= 0) return "Almost done…";
      const secs = Math.ceil(remaining / this.rowsPerSec);
      if (secs < 60) return `~${secs}s remaining`;
      const mins = Math.ceil(secs / 60);
      return `~${mins}m remaining`;
    },
  },

  beforeDestroy() {
    this.closeSSE();
  },

  methods: {
    // ── File selection ──────────────────────────────────────────────────
    onDrop(e) {
      this.dragging = false;
      const file = e.dataTransfer.files[0];
      if (file) this.setFile(file);
    },
    onFileSelected(e) {
      const file = e.target.files[0];
      if (file) this.setFile(file);
    },
    setFile(file) {
      const ok = file.name.endsWith(".xlsx") || file.name.endsWith(".csv");
      if (!ok) {
        this.phase = "error";
        this.errorMsg =
          "Only .xlsx or .csv files are supported. Please convert your file and try again.";
        return;
      }
      this.selectedFile = file;
      this.phase = "selected";
    },

    // ── Upload ─────────────────────────────────────────────────────────
    startUpload() {
      this.phase = "uploading";
      this.uploadPct = 0;

      const formData = new FormData();
      formData.append("file", this.selectedFile);

      const xhr = new XMLHttpRequest();

      xhr.upload.addEventListener("progress", (e) => {
        if (e.lengthComputable) {
          this.uploadPct = Math.round((e.loaded / e.total) * 100);
        }
      });

      xhr.addEventListener("load", () => {
        if (xhr.status === 200) {
          const resp = JSON.parse(xhr.responseText);
          this.jobId = resp.jobId;
          this.phase = "processing";
          this.connectSSE();
        } else {
          this.phase = "error";
          this.errorMsg = `Upload failed: ${xhr.statusText || xhr.status}`;
        }
      });

      xhr.addEventListener("error", () => {
        this.phase = "error";
        this.errorMsg =
          "Network error during upload. Please check your connection and try again.";
      });

      xhr.open("POST", "/site/importpractitioners/");
      xhr.send(formData);
    },

    // ── SSE ─────────────────────────────────────────────────────────────
    connectSSE() {
      this.closeSSE();
      this.eventSource = new EventSource(
        `/site/importpractitioners/${this.jobId}/events`,
      );

      this.eventSource.onmessage = (e) => {
        this.sseErrorCount = 0; // reset on every successful message
        const event = JSON.parse(e.data);
        this.handleSSEEvent(event);
      };

      this.eventSource.onerror = () => {
        // EventSource fires onerror on every automatic reconnect attempt, not just
        // hard failures. Only give up after 3 consecutive errors with no message.
        if (this.phase === "processing") {
          this.sseErrorCount++;
          if (this.sseErrorCount >= 3) {
            this.phase = "error";
            this.errorMsg =
              "Lost connection to server. The import may still be running — " +
              "check back later or retry the upload.";
            this.closeSSE();
          }
          // Below threshold: let EventSource reconnect automatically (~3s retry)
        } else {
          // Normal close (done / idle) — just clean up
          this.closeSSE();
        }
      };
    },

    closeSSE() {
      if (this.eventSource) {
        this.eventSource.close();
        this.eventSource = null;
      }
    },

    handleSSEEvent(event) {
      switch (event.type) {
        case "start":
        case "ready":
          this.procTotal = event.total || 0;
          if (!this.procStartTime) this.procStartTime = Date.now();
          break;

        case "progress":
          this.procCurrent = event.current;
          this.procTotal = event.total;
          break;

        case "row":
          if (event.status === "saved") this.liveSaved++;
          if (event.status === "existing") this.liveExisting++;
          if (event.status === "invalid") this.liveInvalid++;
          // 'saved' events from flushBatch don't carry current — guard to avoid NaN
          if (event.current != null) this.procCurrent = event.current;

          this.feedItems.unshift({
            key: ++this.feedCounter,
            status: event.status,
            empNo: event.empNo || "—",
            name: event.name || "",
            reason: event.reason || "",
          });
          if (this.feedItems.length > 80) this.feedItems.splice(80);
          break;

        case "complete":
          this.finalStats = event.stats;
          this.hasInvalidFile = event.hasInvalidFile;
          this.phase = "done";
          this.closeSSE();
          break;

        case "invalid_columns":
          this.phase = "error";
          this.errorMsg =
            "The file is missing required columns: " +
            event.missing.join(", ") +
            ". Present columns: " +
            event.present.join(", ");
          this.closeSSE();
          break;

        case "error":
          this.phase = "error";
          this.errorMsg = event.message || "An unexpected error occurred.";
          this.closeSSE();
          break;
      }
    },

    // ── Download invalid file ───────────────────────────────────────────
    downloadInvalid() {
      const a = document.createElement("a");
      a.href = `/site/importpractitioners/${this.jobId}/invalid`;
      a.download = "invalid_practitioners.xlsx";
      a.click();
    },

    // ── Reset ───────────────────────────────────────────────────────────
    reset() {
      this.closeSSE();
      this.phase = "idle";
      this.dragging = false;
      this.selectedFile = null;
      this.uploadPct = 0;
      this.jobId = null;
      this.procCurrent = 0;
      this.procTotal = 0;
      this.liveSaved = 0;
      this.liveExisting = 0;
      this.liveInvalid = 0;
      this.feedItems = [];
      this.feedCounter = 0;
      this.procStartTime = null;
      this.sseErrorCount = 0;
      this.finalStats = {};
      this.hasInvalidFile = false;
      this.errorMsg = "";
      if (this.$refs.fileInput) this.$refs.fileInput.value = "";
    },

    // ── Helpers ─────────────────────────────────────────────────────────
    feedIcon(status) {
      return (
        {
          saved: "mdi-check-circle-outline",
          existing: "mdi-account-check-outline",
          invalid: "mdi-alert-circle-outline",
        }[status] || "mdi-dots-horizontal"
      );
    },

    formatBytes(bytes) {
      if (!bytes) return "0 B";
      const k = 1024;
      const sizes = ["B", "KB", "MB", "GB"];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
    },
  },
};
</script>

